<?php
require_once __DIR__ . '/../includes/layout.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){ execute('UPDATE fines SET status=?,notes=? WHERE id=?',[$_POST['status'],trim($_POST['notes']??''),(int)$_POST['id']]); flash('Status denda diperbarui.'); redirect('admin/fines.php'); }
$data=rows('SELECT f.*,u.name,u.member_id,b.title FROM fines f JOIN users u ON u.id=f.user_id LEFT JOIN borrowings br ON br.id=f.borrowing_id LEFT JOIN books b ON b.id=br.book_id ORDER BY f.created_at DESC'); page_head('Denda',true); admin_heading('Denda & Sanksi','Kelola denda keterlambatan dan kehilangan');
?><section class="card table-card"><table><thead><tr><th>Anggota</th><th>Buku</th><th>Jenis</th><th>Hari</th><th>Jumlah</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($data as $row): ?><tr><td><?=e($row['name'])?><br><small class="muted"><?=e($row['member_id'])?></small></td><td><?=e($row['title']??'-')?></td><td><?=e($row['type'])?></td><td><?=e($row['days_late'])?></td><td><?=rupiah((int)$row['amount'])?></td><td><?=status_badge($row['status'])?></td><td><?php if($row['status']==='unpaid'): ?><form method="post" class="actions"><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="status" value="paid"><input type="hidden" name="notes" value="Dibayar melalui kasir"><button class="success">Tandai lunas</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></section><?php page_foot(true); ?>
